content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-03-anti-addiction-008

=== 用户原始指令 (query.txt) ===
帮我整一个防沉迷卡片 上面列几个APP的使用时长 数字会动的那种 点一下能进APP 快超时了要提醒

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我整一个防沉迷卡片 上面列几个APP的使用时长 数字会动的那种 点一下能进APP 快超时了要提醒",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "parent_control"
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "antiAddiction": {
        "title": {
          "type": "string",
          "description": "防沉迷卡片标题",
          "sampleValue": "健康使用"
        },
        "statusText": {
          "type": "string",
          "description": "当前防沉迷状态提醒文案",
          "sampleValue": "抖音剩余 8 分钟"
        },
        "totalUsageText": {
          "type": "string",
          "description": "今日应用总使用时长展示文本",
          "sampleValue": "3小时12分"
        },
        "limitText": {
          "type": "string",
          "description": "今日使用时长限制展示文本",
          "sampleValue": "上限4小时"
        },
        "usageValue": {
          "type": "number",
          "description": "今日总使用进度数值，单位为分钟",
          "sampleValue": 192
        },
        "usageTotal": {
          "type": "number",
          "description": "今日总使用上限数值，单位为分钟",
          "sampleValue": 240
        },
        "apps": {
          "type": "array",
          "description": "需要展示使用时长的应用列表样例",
          "sampleValue": [
            {
              "name": "抖音",
              "timeText": "52分",
              "remainText": "剩8分",
              "progressValue": 52,
              "progressTotal": 60
            },
            {
              "name": "游戏",
              "timeText": "45分",
              "remainText": "剩15分",
              "progressValue": 45,
              "progressTotal": 60
            },
            {
              "name": "视频",
              "timeText": "36分",
              "remainText": "正常",
              "progressValue": 36,
              "progressTotal": 90
            }
          ],
          "items": {
            "type": "object",
            "description": "单个应用使用时长条目",
            "properties": {
              "name": {
                "type": "string",
                "description": "应用名称",
                "sampleValue": "抖音"
              },
              "timeText": {
                "type": "string",
                "description": "应用今日已使用时长展示文本",
                "sampleValue": "52分"
              },
              "remainText": {
                "type": "string",
                "description": "应用距离超时的剩余时间或状态文案",
                "sampleValue": "剩8分"
              },
              "progressValue": {
                "type": "number",
                "description": "应用今日已使用时长数值，单位为分钟",
                "sampleValue": 52
              },
              "progressTotal": {
                "type": "number",
                "description": "应用今日使用上限数值，单位为分钟",
                "sampleValue": 60
              }
            }
          }
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_timing.png",
      "description": "防沉迷计时图标，适合用于应用使用时长、健康使用和接近超时提醒的视觉识别。"
    }
  ]
}

